import {loadProjectBundle,rememberProjectBundle} from '@/lib/db';
import type {SourceEdit,WriteResult} from './host';
import {canonicalStandaloneTag,decodeStandaloneBundle,encodeStandaloneBundle,type StandaloneNode} from './standalone-model';
import {saveCampaignBundle} from '@/bannermatic/campaign';
import {snapshotBrowserProjectFS} from './fs';
import {flushAttachedLibrary} from '@/engine/library';
export {canonicalStandaloneTag,decodeStandaloneBundle,encodeStandaloneBundle} from './standalone-model';
export type {StandaloneBundleModel,StandaloneNode} from './standalone-model';

const resolved=(value:string|undefined,ids:Record<string,string>)=>value?ids[value]||value:value;
const writeQueues=new Map<string,Promise<WriteResult>>();

async function apply(projectId:string,edits:SourceEdit[]):Promise<WriteResult>{const dir=`__browser_standalone__:${projectId}`;await flushAttachedLibrary(dir);const current=await loadProjectBundle(projectId),model=current&&decodeStandaloneBundle(current);if(!model)return{skipped:[],error:'This browser project does not contain an editable standalone model.'};const ids:Record<string,string>={};for(const edit of edits){if(edit.kind==='insert'){const source=`bannermatic-edit:${crypto.randomUUID()}`;ids[edit.source]=source;const parent=resolved(edit.parent,ids);const node:StandaloneNode={source,tag:canonicalStandaloneTag(edit.tag),props:{...edit.props},...(parent?{parent}:{}),...(edit.text===undefined?{}:{text:edit.text})};const before=resolved(edit.before,ids),index=before?model.nodes.findIndex(item=>item.source===before):-1;model.nodes.splice(index>=0?index:model.nodes.length,0,node)}else if(edit.kind==='set'){const node=model.nodes.find(item=>item.source===resolved(edit.source,ids));if(node){node.props={...node.props,...edit.props};if(edit.text!==undefined)node.text=edit.text}}else if(edit.kind==='move'){const source=resolved(edit.source,ids),index=model.nodes.findIndex(item=>item.source===source);if(index>=0){const [node]=model.nodes.splice(index,1);node!.parent=resolved(edit.parent,ids);const before=resolved(edit.before,ids),target=before?model.nodes.findIndex(item=>item.source===before):-1;model.nodes.splice(target>=0?target:model.nodes.length,0,node!)}}else if(edit.kind==='remove'){const source=resolved(edit.source,ids),doomed=new Set([source]);let changed=true;while(changed){changed=false;for(const node of model.nodes)if(node.parent&&doomed.has(node.parent)&&!doomed.has(node.source)){doomed.add(node.source);changed=true}}model.nodes=model.nodes.filter(node=>!doomed.has(node.source))}}
 model.assets=await snapshotBrowserProjectFS(dir);const bundle=encodeStandaloneBundle(model);await rememberProjectBundle(projectId,bundle);if(model.campaignId)await saveCampaignBundle(model.campaignId,bundle);return{skipped:[],ids,unrolled:[]}}

export function applyStandaloneEdits(projectId:string,edits:SourceEdit[]):Promise<WriteResult>{const previous=writeQueues.get(projectId)||Promise.resolve({skipped:[]} as WriteResult),next=previous.catch(()=>({skipped:[]} as WriteResult)).then(()=>apply(projectId,edits));writeQueues.set(projectId,next);void next.finally(()=>{if(writeQueues.get(projectId)===next)writeQueues.delete(projectId)});return next}
